1	/**
2	 * Organization Module — single source of truth for departments, phases, and
3	 * the agent registry. Replaces the hardcoded AGENT_PIPELINE / AGENT_ROLES
4	 * constants previously in server.js.
5	 *
6	 * Data lives in ~/.claude/org/:
7	 *   - departments.json — department + phase definitions
8	 *   - registry.json    — per-agent record (department, phase, reportsTo,
9	 *                        experience, level, skills, status, hire date)
10	 *
11	 * This module is pure — it reads/writes JSON. Experience computation lives
12	 * in src/experience.js and reads from here.
13	 */
14	
15	const fs = require('fs');
16	const path = require('path');
17	const os = require('os');
18	const db = require('./db');
19	
20	const HOME = os.homedir();
21	const ORG_DIR = path.join(HOME, '.claude', 'org');
22	const DEPARTMENTS_PATH = path.join(ORG_DIR, 'departments.json');
23	const REGISTRY_PATH = path.join(ORG_DIR, 'registry.json');
24	
25	function ensureDir(dir) {
26	  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
27	}
28	
29	function readJson(filePath, fallback) {
30	  try {
31	    if (!fs.existsSync(filePath)) return fallback;
32	    return JSON.parse(fs.readFileSync(filePath, 'utf-8'));
33	  } catch (err) {
34	    console.warn(`[org] failed to read ${filePath}: ${err.message}`);
35	    return fallback;
36	  }
37	}
38	
39	function writeJson(filePath, data) {
40	  ensureDir(path.dirname(filePath));
41	  // Atomic write: write to .tmp then rename
42	  const tmp = filePath + '.tmp';
43	  fs.writeFileSync(tmp, JSON.stringify(data, null, 2));
44	  fs.renameSync(tmp, filePath);
45	}
46	
47	// ──────────────────────────────────────────────────────────────────────────
48	//  Departments & Phases
49	// ──────────────────────────────────────────────────────────────────────────
50	
51	function loadDepartments() {
52	  return db.loadDepartments();
53	}
54	
55	function saveDepartments(data) {
56	  data.updatedAt = new Date().toISOString();
57	  db.saveDepartments(data);
58	}
59	
60	function listDepartments() {
61	  const { departments } = loadDepartments();
62	  return Object.values(departments || {})
63	    .filter((d) => d.active !== false)
64	    .sort((a, b) => (a.order || 0) - (b.order || 0));
65	}
66	
67	function getDepartment(id) {
68	  const { departments } = loadDepartments();
69	  return departments?.[id] || null;
70	}
71	
72	function listPhases() {
73	  const { phases } = loadDepartments();
74	  return Object.values(phases || {}).sort((a, b) => (a.order || 0) - (b.order || 0));
75	}
76	
77	function getPhase(id) {
78	  const { phases } = loadDepartments();
79	  return phases?.[id] || null;
80	}
81	
82	// ──────────────────────────────────────────────────────────────────────────
83	//  Registry
84	// ──────────────────────────────────────────────────────────────────────────
85	
86	function loadRegistry() {
87	  return db.loadRegistry();
88	}
89	
90	function saveRegistry(data) {
91	  data.updatedAt = new Date().toISOString();
92	  db.saveRegistry(data);
93	}
94	
95	function listAgentRecords() {
96	  const { agents } = loadRegistry();
97	  return Object.values(agents || {});
98	}
99	
100	function findAgent(id) {
101	  const { agents } = loadRegistry();
102	  return agents?.[id] || null;
103	}
104	
105	// upsertOpts: { skipHistory?: boolean, action?: string, batchId?: string, actor?: string, skipBroadcast?: boolean }
106	function upsertAgent(id, patch, opts = {}) {
107	  const registry = loadRegistry();
108	  registry.agents = registry.agents || {};
109	  const existing = registry.agents[id] || { id };
110	  const next = {
111	    ...existing,
112	    ...patch,
113	    id,
114	    updatedAt: new Date().toISOString(),
115	  };
116	  registry.agents[id] = next;
117	  saveRegistry(registry);
118	
119	  // Audit + undo history (write before broadcast so undo always has prior state)
120	  if (!opts.skipHistory) {
121	    try {
122	      db.logHistory({
123	        agent_id: id,
124	        action: opts.action || 'upsert',
125	        prior_state: existing,
126	        new_state: next,
127	        patch,
128	        actor: opts.actor || 'admin',
129	        batch_id: opts.batchId || null,
130	      });
131	    } catch (err) {
132	      console.warn('[org] history log failed:', err.message);
133	    }
134	  }
135	
136	  // Broadcast via SSE so all connected pages refresh in real time
137	  if (!opts.skipBroadcast) {
138	    try {
139	      const { events } = require('./lib/agentSync');
140	      events.emit('agent:upsert', { agentId: id, agent: next });
141	    } catch (err) {
142	      // agentSync may not be initialised in some contexts (tests, scripts)
143	    }
144	  }
145	
146	  return next;
147	}
148	
149	function removeAgent(id) {
150	  const registry = loadRegistry();
151	  if (registry.agents?.[id]) {
152	    delete registry.agents[id];
153	    saveRegistry(registry);
154	    return true;
155	  }
156	  return false;
157	}
158	
159	function findAgentsByDepartment(departmentId) {
160	  return listAgentRecords().filter((a) => a.department === departmentId);
161	}
162	
163	function findDirectReports(managerId) {
164	  return listAgentRecords().filter((a) => a.reportsTo === managerId);
165	}
166	
167	/**
168	 * Filter agents by tag query.
169	 * Logic: AND across categories, OR within each category.
170	 * tagQuery: { tech?: string[], domain?: string[], 'work-type'?: string[] }
171	 */
172	function findAgentsByTags(tagQuery = {}) {
173	  return listAgentRecords().filter((a) => {
174	    const tags = a.tags || { tech: [], domain: [], 'work-type': [] };
175	    for (const [cat, values] of Object.entries(tagQuery)) {
176	      if (!values || values.length === 0) continue;
177	      const agentCatTags = tags[cat] || [];
178	      if (!values.some((v) => agentCatTags.includes(v))) return false;
179	    }
180	    return true;
181	  });
182	}
183	
184	// ──────────────────────────────────────────────────────────────────────────
185	//  Org chart composition — combines registry records with disk-parsed agents
186	// ──────────────────────────────────────────────────────────────────────────
187	
188	/**
189	 * Build a complete org-chart response combining:
190	 *   - Department metadata from departments.json
191	 *   - Per-agent records from registry.json
192	 *   - Live agent metadata (name, description, model, tools) from the
193	 *     caller-supplied `agentMap` keyed by filename
194	 *
195	 * `agentMap` is injected so this module stays decoupled from server.js's
196	 * agent parser. Typical caller:
197	 *
198	 *   const agentMap = Object.fromEntries(
199	 *     listAgents(path.join(CLAUDE_DIR, 'agents')).map((a) => [a.filename, a])
200	 *   );
201	 *   const chart = org.buildOrgChart(agentMap);
202	 */
203	function buildOrgChart(agentMap = {}) {
204	  const { departments, phases } = loadDepartments();
205	  const { agents: registry } = loadRegistry();
206	
207	  // Phase A — pull live load + capacity for every agent in one query so the
208	  // chart can render 🟢🟡🔴 indicators without N round-trips.
209	  // tasks lib is required lazily to avoid a circular dep at module load.
210	  let loadMap = {};
211	  try {
212	    const tasksLib = require('./lib/tasks');
213	    loadMap = tasksLib.getAllAgentLoad();
214	  } catch (err) {
215	    // Graceful degradation: no load info if tasks lib not yet available.
216	    loadMap = {};
217	  }
218	
219	  const nodes = [];
220	  const agentIds = Object.keys(registry || {});
221	
222	  for (const id of agentIds) {
223	    const record = registry[id];
224	    const disk = agentMap[id] || null;
225	
226	    // Skip if registry references an agent that has no .md file on disk
227	    // (we still keep it if status === 'probation' for new hires in flight)
228	    if (!disk && record.status !== 'probation' && record.status !== 'pending') {
229	      continue;
230	    }
231	
232	    const deptInfo = departments?.[record.department] || null;
233	
234	    // Org Structure v2: sub-department + pod resolution
235	    const subDeptInfo = (record.subDepartment && deptInfo?.subDepartments)
236	      ? deptInfo.subDepartments[record.subDepartment] || null
237	      : null;
238	
239	    const deptColor = deptInfo?.color || '#6b7280';
240	
241	    nodes.push({
242	      id,
243	      name: disk?.name || record.name || id,
244	      title: record.title || 'Agent',
245	      tier: record.tier || 'engineer',
246	      model: disk?.model || record.model || 'sonnet',
247	      tools: disk?.tools || '',
248	      description: disk?.description || record.description || '',
249	      department: record.department || null,
250	      departmentLabel: deptInfo?.label || null,
251	      departmentColor: deptColor,
252	      // Org v2 fields
253	      subDepartment: record.subDepartment || null,
254	      subDepartmentLabel: subDeptInfo?.label || null,
255	      subDepartmentDescription: subDeptInfo?.description || null,
256	      subDepartmentOrder: subDeptInfo?.order ?? 999,
257	      pod: record.pod || null,
258	      secondaryReportsTo: record.secondaryReportsTo || null,
259	      // phase removed 2026-04-28; phaseColor kept (= deptColor) for legacy tinting refs
260	      phase: null,
261	      phaseLabel: null,
262	      phaseColor: deptColor,
263	      reportsTo: record.reportsTo || null,
264	      status: record.status || 'active',
265	      level: record.level ?? null,
266	      levelTitle: record.levelTitle ?? null,
267	      yearsOfExperience: record.yearsOfExperience ?? null,
268	      experiencePoints: record.experiencePoints ?? null,
269	      tags: record.tags || { tech: [], domain: [], 'work-type': [] },
270	      squad: record.squad || null,
271	      // Phase A — live capacity + perf signals for the org-chart UI
272	      activeTaskCount: loadMap[id]?.activeTaskCount ?? 0,
273	      maxConcurrentTasks: loadMap[id]?.maxConcurrentTasks ?? 3,
274	      loadStatus: loadMap[id]?.loadStatus ?? 'free',
275	      busyUntilAt: loadMap[id]?.busyUntilAt ?? null,
276	      lastDispatchAt: loadMap[id]?.lastDispatchAt ?? null,
277	      successRate: typeof record.stats?.successRate === 'number' ? record.stats.successRate : null,
278	      avgDurationMs: record.stats?.avgDurationMs ?? null,
279	    });
280	  }
281	
282	  // Edges: reporting lines
283	  const nodeById = Object.fromEntries(nodes.map((n) => [n.id, n]));
284	  const edges = [];
285	  for (const node of nodes) {
286	    if (node.reportsTo && nodeById[node.reportsTo]) {
287	      edges.push({ from: node.reportsTo, to: node.id });
288	    }
289	  }
290	
291	  // Departments in org view (Org Structure v2 — includes subDepartments map)
292	  const departmentList = Object.values(departments || {})
293	    .filter((d) => d.active !== false)
294	    .sort((a, b) => (a.order || 0) - (b.order || 0))
295	    .map((d) => {
296	      const members = nodes.filter((n) => n.department === d.id);
297	      // Sub-department buckets (sorted by subDepartmentOrder, then alphabetical)
298	      const subDepartments = Object.values(d.subDepartments || {})
299	        .sort((a, b) => (a.order ?? 999) - (b.order ?? 999))
300	        .map((sd) => ({
301	          id: sd.id,
302	          label: sd.label,
303	          description: sd.description,
304	          order: sd.order ?? 999,
305	          pod: sd.pod || null,
306	          members: members
307	            .filter((n) => n.subDepartment === sd.id)
308	            .sort((a, b) => {
309	              // Leadership tier first inside a sub-dept, then by id
310	              if (a.tier === 'leadership' && b.tier !== 'leadership') return -1;
311	              if (a.tier !== 'leadership' && b.tier === 'leadership') return 1;
312	              return a.id.localeCompare(b.id);
313	            }),
314	        }));
315	      // Orphans: members in this department but with no/unknown subDepartment
316	      const knownSubIds = new Set(subDepartments.map((s) => s.id));
317	      const orphanMembers = members.filter((n) => !n.subDepartment || !knownSubIds.has(n.subDepartment));
318	
319	      return {
320	        id: d.id,
321	        label: d.label,
322	        description: d.description,
323	        color: d.color,
324	        icon: d.icon,
325	        head: d.head,
326	        members,
327	        subDepartments,
328	        orphanMembers,
329	      };
330	    });
331	
332	  // Stats
333	  const stats = {
334	    totalAgents: nodes.length,
335	    byModel: {},
336	    byTier: {},
337	    byDepartment: {},
338	    byStatus: {},
339	    byLevel: {},
340	  };
341	  for (const n of nodes) {
342	    stats.byModel[n.model] = (stats.byModel[n.model] || 0) + 1;
343	    stats.byTier[n.tier] = (stats.byTier[n.tier] || 0) + 1;
344	    if (n.department) stats.byDepartment[n.department] = (stats.byDepartment[n.department] || 0) + 1;
345	    stats.byStatus[n.status] = (stats.byStatus[n.status] || 0) + 1;
346	    if (n.level != null) stats.byLevel[n.level] = (stats.byLevel[n.level] || 0) + 1;
347	  }
348	
349	  return {
350	    nodes,
351	    edges,
352	    phases: [],
353	    departments: departmentList,
354	    stats,
355	  };
356	}
357	
358	// ──────────────────────────────────────────────────────────────────────────
359	//  Self-heal: detect drift between registry and disk
360	// ──────────────────────────────────────────────────────────────────────────
361	
362	/**
363	 * Compare registry.json against the actual agent .md files on disk.
364	 * Returns { onlyOnDisk: [], onlyInRegistry: [] } — agents present in one
365	 * but not the other. HR uses this to auto-heal the registry.
366	 */
367	function detectDrift(agentMap) {
368	  const { agents: registry } = loadRegistry();
369	  const registryIds = new Set(Object.keys(registry || {}));
370	  const diskIds = new Set(Object.keys(agentMap));
371	
372	  const onlyOnDisk = [...diskIds].filter((id) => !registryIds.has(id));
373	  const onlyInRegistry = [...registryIds].filter(
374	    (id) => !diskIds.has(id) && registry[id].status !== 'probation'
375	  );
376	
377	  return { onlyOnDisk, onlyInRegistry };
378	}
379	
380	module.exports = {
381	  // paths (exposed for HR module)
382	  ORG_DIR,
383	  DEPARTMENTS_PATH,
384	  REGISTRY_PATH,
385	
386	  // departments
387	  loadDepartments,
388	  saveDepartments,
389	  listDepartments,
390	  getDepartment,
391	  listPhases,
392	  getPhase,
393	
394	  // registry
395	  loadRegistry,
396	  saveRegistry,
397	  listAgentRecords,
398	  findAgent,
399	  upsertAgent,
400	  removeAgent,
401	  findAgentsByDepartment,
402	  findAgentsByTags,
403	  findDirectReports,
404	
405	  // compose
406	  buildOrgChart,
407	  detectDrift,
408	};
