3	const { Router } = require('express');
4	const path = require('path');
5	const os = require('os');
6	const { rateLimit } = require('../middleware/rateLimit');
7	const { listAgents } = require('../lib/cache');
8	const db = require('../db');
9	const org = require('../org');
10	const experience = require('../experience');
11	const hr = require('../hr');
12	const agentSync = require('../lib/agentSync');
13	const taxonomy = require('../taxonomy');
14	
15	const router = Router();
16	
17	const HOME = os.homedir();
18	const CLAUDE_DIR = path.join(HOME, '.claude');
19	
20	function loadRecentAgentRuns(hours = 24) {
21	  try {
22	    return db.getRecentAgentRuns(hours);
23	  } catch {
24	    return [];
25	  }
26	}
27	
28	// GET /api/org-chart
29	router.get('/org-chart', rateLimit('read'), (req, res) => {
30	  try {
31	    const globalAgents = listAgents(path.join(CLAUDE_DIR, 'agents'));
32	    const agentMap = {};
33	    for (const a of globalAgents) {
34	      agentMap[a.filename] = a;
35	    }
36	    const chart = org.buildOrgChart(agentMap);
37	    res.json(chart);
38	  } catch (err) {
39	    res.status(500).json({ error: err.message });
